args.command:
perl -e '
use strict;
use warnings;

# Persistent entity types (table-backed domain structs)
my @entities = qw(
  Attachment User Memo Reaction Inbox MemoRelation MemoShare
  IdentityProvider InstanceSetting UserSetting UserIdentity
  AuthenticationConfigState MemoShare
);

# Also consider proto store entities? skip for now

# Collect go files
open my $find, "find /bench/repo -name \"*.go\" ! -path \"*/web/*\" ! -path \"*/.git/*\" ! -path \"*/proto/gen/*\" |" or die;
my @files;
while (<$find>) { chomp; push @files, $_; }
close $find;

sub is_store_layer {
  my ($p) = @_;
  return $p =~ m{/store/} || $p =~ m{/store\.go$};
}

sub pkg_of {
  my ($p) = @_;
  $p =~ s{/[^/]+\.go$}{};
  $p =~ s{^/bench/repo/}{};
  return $p;
}

my %content;
my %pkgname;
for my $p (@files) {
  open my $fh, "<", $p or die;
  local $/;
  $content{$p} = <$fh>;
  close $fh;
  if ($content{$p} =~ /^package\s+(\w+)/m) { $pkgname{$p} = $1; }
}

print sprintf("%-28s %6s  packages\n", "entity", "npkg");
my %rank;
for my $ent (@entities) {
  my %pkgs;
  my @hits;
  for my $p (@files) {
    next if is_store_layer($p);
    my $t = $content{$p};
    # store.Entity or store.Entity, as a type reference
    if ($t =~ /\bstore\.$ent\b/) {
      my $pkg = pkg_of($p);
      $pkgs{$pkg} = 1;
      push @hits, $pkg unless grep { $_ eq $pkg } @hits;
    }
  }
  my $n = scalar keys %pkgs;
  $rank{$ent} = $n;
  printf "%-28s %6d  %s\n", $ent, $n, join(", ", sort keys %pkgs);
}
'

# Check IDP/settings usage and storepb entity types
echo "===== store.IdentityProvider ====="
grep -rn --include="*.go" "store.IdentityProvider\|store.InstanceSetting\|store.UserSetting" /bench/repo --exclude-dir=web --exclude-dir=.git --exclude-dir=proto | grep -v "/store/" | head -30

echo "===== storepb common entities ====="
perl -e '
use strict;
my @ents = qw(Memo User Attachment Reaction Inbox IdentityProvider InstanceSetting UserSetting UserIdentity MemoPayload AttachmentPayload);
open my $find, "find /bench/repo -name \"*.go\" ! -path \"*/web/*\" ! -path \"*/.git/*\" |" or die;
my @files; while (<$find>) { chomp; push @files, $_; }
sub pkg { my $p=shift; $p=~s{/[^/]+\.go$}{}; $p=~s{^/bench/repo/}{}; $p }
sub store_layer { $_[0] =~ m{/store/} || $_[0] =~ m{/store\.go$} || $_[0] =~ m{/proto/} }
for my $ent (@ents) {
  my %pkgs;
  for my $p (@files) {
    next if store_layer($p);
    open my $fh, "<", $p or next;
    local $/; my $t = <$fh>;
    if ($t =~ /\bstorepb\.$ent\b/) { $pkgs{pkg($p)}=1; }
  }
  printf "storepb.%-22s %d  %s\n", $ent, scalar(keys %pkgs), join(", ", sort keys %pkgs);
}
'

echo "===== all store.TYPE refs by package (non-store) ====="
grep -rhn --include="*.go" -o "store\.[A-Z][A-Za-z0-9]*" /bench/repo --exclude-dir=web --exclude-dir=.git --exclude-dir=proto --exclude-dir=store | sort | uniq -c | sort -rn | head -40
